"""Build BBLO's review pages from approved directory and activity content."""
from pathlib import Path
import csv, json, re, html

REPO = Path(__file__).resolve().parents[1]
ROOT = REPO / 'website-preview'
BASE = '/website-preview'
VERSION = '20261103-bblo-community'
def esc(s): return html.escape(str(s), quote=True)
def href(path): return BASE + path
def link(path,label,cls='button'): return f'<a class="{cls}" href="{href(path)}">{label}</a>'
def section(body, cls=''): return f'<section class="{cls}"><div class="wrap">{body}</div></section>'
def hero(eyebrow,title,copy,actions=''): return section(f'<p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="lead">{copy}</p>{actions}','hero')
def photo(src,alt,caption='',cls=''):
 return f'<figure class="photo {cls}"><img src="{BASE}/assets/{src}" alt="{esc(alt)}" loading="lazy" decoding="async">'+(f'<figcaption>{caption}</figcaption>' if caption else '')+'</figure>'

sections=[('/bblo/','About BBLO'),('/bblo/join/','How to Join'),('/bblo/members/','Meet Our Members'),('/bblo/board/','Meet Our Board'),('/bblo/community-impact/','Our Community Impact'),('/bblo/testimonials/','Testimonials'),('/bblo/present/','Interested in Presenting?'),('/bblo/support/','Support BBLO'),('/bblo/member-center/#member-check-in','Member Check-in'),('/bblo/member-center/#member-win','Report Wins')]
dropdown='<details class="nav-dropdown"><summary>BBLO <span aria-hidden="true">⌄</span></summary><div class="dropdown-links">'+''.join(link(p,t,'') for p,t in sections)+'</div></details>'
template=(ROOT/'bblo/index.html').read_text()
header=re.search(r'<header>.*?</header>',template,re.S).group()
header=header.replace(f'<a href="{BASE}/bblo/">BBLO</a>',dropdown)
footer=re.search(r'<footer>.*?</footer>',template,re.S).group()
def subnav(active):
 return '<nav class="bblo-subnav" aria-label="BBLO sections">'+''.join(f'<a href="{href(p)}"'+(' aria-current="page"' if p.split('#')[0]==active else '')+f'>{t}</a>' for p,t in sections[:8])+'</nav>'
def page(route,title,description,body,image='photos/bblo-october-group.webp'):
 document=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{esc(title)} | BBLO · TLC</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="https://doitwithtlc.com{route}"><meta property="og:title" content="{esc(title)} | BBLO"><meta property="og:description" content="{esc(description)}"><meta property="og:type" content="website"><meta property="og:url" content="https://doitwithtlc.com{route}"><meta property="og:image" content="https://doitwithtlc.com{BASE}/assets/{image}"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="{BASE}/assets/design.css?v={VERSION}"><link rel="stylesheet" href="{BASE}/assets/bblo/bblo.css?v={VERSION}"><script src="{BASE}/assets/site.js?v={VERSION}" defer></script><script src="{BASE}/assets/bblo/bblo.js?v={VERSION}" defer></script></head><body><a class="skip" href="#main">Skip to content</a>{header}{subnav(route)}<main id="main" class="bblo-page">{body}</main>{footer}</body></html>'''
 file=ROOT/route.strip('/')/'index.html';file.parent.mkdir(parents=True,exist_ok=True);file.write_text(document)

members=json.loads((REPO/'data/bblo-members.json').read_text())

def member_card(m):
 image=photo(m['photo'],m['name'],cls='directory-portrait') if m['photo'] else ''
 return f'<article class="card member-card" data-member="{esc(m["company"]+" "+m["name"]+" "+m["category"])}">{image}<p class="member-person">{esc(m["name"])}</p><h3>{esc(m["company"])}</h3><p>{esc(m["category"])}</p>'+link('/bblo/members/'+m['slug']+'/', 'View member &amp; contact details →','text-link')+'</article>'
def contacts(m):
 blocks=[]
 for n,number in enumerate(re.findall(r'\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}',m['phone'])):
  digits=re.sub(r'\D','',number);label='Phone'
  if m['slug']=='legacy-insurance':label=['Cell','Office'][min(n,1)]
  elif m['slug']=='rc-home-pros':label=['Office','Español'][min(n,1)]
  elif m['slug']=='martinez-roofing':label=['Office','Cell'][min(n,1)]
  blocks.append(f'<div><dt>{label}</dt><dd><a href="tel:+1{digits}">{esc(number)}</a></dd></div>')
 if m['email']:blocks.append(f'<div><dt>Email</dt><dd><a href="mailto:{esc(m["email"])}">{esc(m["email"])}</a></dd></div>')
 return '<dl class="contact-list">'+''.join(blocks)+'</dl>'
for m in members:
 social=''.join(f'<a class="button secondary" href="{esc(m[key])}" target="_blank" rel="noopener">{label} ↗</a>' for key,label in [('facebook','Facebook'),('instagram','Instagram'),('website','Website')] if m[key])
 image=photo(m['photo'],m['name'],esc(m['photo_credit']),'member-profile-photo') if m['photo'] else ''
 body=hero('Meet our members',esc(m['name']),esc(m['company']))
 body+=section('<div class="member-profile-layout"><div><p class="eyebrow">Their business</p><h2>'+esc(m['company'])+'</h2><p class="lead">'+esc(m['category'])+'</p><h3>Connect directly.</h3>'+contacts(m)+'<div class="actions">'+social+'</div><p class="note">Business contact information supplied in BBLO’s member referral list. Available social and website links are shown.</p></div>'+image+'</div>')
 if m.get('quote') and m.get('quote_approved'):
  body+=section('<p class="eyebrow">Their BBLO experience</p><blockquote class="member-quote"><p>'+esc(m['quote'])+'</p><cite>'+esc(m['name'])+' · '+esc(m['company'])+'</cite></blockquote>','map-section')
 body+=section('<p class="eyebrow">The BBLO connection</p><h2>Behind every business is a person.</h2><p>Get to know our members through business spotlights, education and community participation.</p><div class="actions">'+link('/bblo/testimonials/#share-story','Members: share your BBLO experience')+link('/bblo/members/','← Meet more members','button secondary')+'</div>','map-section')
 page('/bblo/members/'+m['slug']+'/',m['name']+' · '+m['company'],m['category']+' — contact details and available business links.',body,m['photo'] or 'photos/bblo-october-group.webp')

directory=hero('Meet our members','Local businesses.<br><em>People you can connect with.</em>','Search by name, business or service. Open a profile for contact information, available social links and the company website.')
directory+=section('<label class="directory-label" for="member-search">Find a member or service</label><input id="member-search" class="member-search" type="search" placeholder="Try roofing, photography, Jose…"><p id="member-count" class="note" role="status" aria-live="polite">17 businesses</p><div class="grid three member-directory">'+''.join(member_card(m) for m in members)+'</div><p id="member-empty" hidden>No matching business. Try another name or service.</p><div class="actions">'+link('/bblo/testimonials/#profile-update','Members: update your profile','button secondary')+'</div>')
page('/bblo/members/','Meet Our Members','Find BBLO member businesses, contact details and available Facebook, Instagram and website links.',directory)

partners={
'habitat':dict(name='Habitat for Humanity of Marion County',kind='Nonprofit partner',website='https://habitatocala.org/',contact='https://habitatocala.org/contact/',phone='352-351-4663',email='',address='1321 SE 25th Loop, Suite 103, Ocala, FL 34471',about='Local housing nonprofit and the organization behind the Vet Build archive.'),
'rock':dict(name='The Rock Program',kind='Nonprofit program',website='https://therockprogram.org/',contact='https://therockprogram.org/contact-us/',phone='352-304-9288',email='info@therockprogram.org',address='',about='A program of Empowered of Central Florida that helps meet local students’ essential needs.'),
'champions':dict(name='Champions for Champions',kind='Nonprofit partner',website='https://championsforchampions.org/',contact='https://championsforchampions.org/contact-us/',phone='352-462-0380',email='',address='240 SE 17th St., Suite C, Ocala, FL 34471',about='An organization providing inclusive programs for people with special needs and their families.'),
'emergency':dict(name='Marion County Emergency Management',kind='Public agency',website='https://www.marionso.com/emergency-management',contact='https://www.marionso.com/emergency-management-volunteering',phone='352-369-8100',email='emiller@marionso.com',address='',about='The county’s emergency preparedness and coordination team. This community partner is a public agency.')}
albums=[
 dict(slug='habitat-vet-build',title='Habitat Vet Build',date='July 10, 2026',type='Community build archive',cover='bblo/community/habitat-group.webp',partners=['habitat'],intro='BBLO’s sponsored community-build archive brings together the people, the build site and the shared work.',doing='The photographs document participants together at a Habitat build site and hands-on work in progress. They are shared as a record of BBLO’s community participation.',photos=[('bblo/community/habitat-group.webp','Participants gathered at the Habitat build site.'),('bblo/community/habitat-team.webp','A moment together with the build team.'),('photos/bblo-habitat-build.jpg','Hands-on activity from the BBLO-sponsored Habitat build archive.')]),
 dict(slug='emergency-management-tour',title='Marion County Emergency Management Tour',date='August 14, 2026',type='Field Trip Friday',cover='bblo/community/emergency-group.webp',partners=['emergency'],intro='A Field Trip Friday focused on the people and resources behind Marion County’s emergency preparedness.',doing='BBLO’s event information described a guided tour, a look at how Marion County prepares for and responds to emergencies, and questions with Emergency Management staff. These photos show the group, the communications area and discussion during the visit.',photos=[('bblo/community/emergency-group.webp','BBLO visitors at the Marion County Emergency Operations Center.'),('bblo/community/emergency-radio-team.webp','A look inside the emergency radio communications area.'),('bblo/community/emergency-tour.webp','Conversation during the guided visit.')]),
 dict(slug='community-nonprofit-spotlights',title='Community Nonprofit Spotlights',date='September 4, 2026',type='Nonprofit presentations at BBLO',cover='bblo/community/nonprofit-group.webp',partners=['rock','champions'],intro='Local nonprofit conversations at Media Minds, with The Rock Program and Champions for Champions identified in the BBLO archive.',doing='The meeting photographs show nonprofit presentations, discussion with attendees and a group photo. The purpose of this album is to connect the conversation at BBLO with the organizations’ own information and ways to get involved.',photos=[('bblo/community/nonprofit-conversation.webp','A nonprofit conversation with BBLO attendees at Media Minds.'),('bblo/community/nonprofit-presentation.webp','A nonprofit presentation and invitation to connect.'),('bblo/community/nonprofit-group.webp','The group together at the September 4 meeting.')])]
def albumcard(a):
 return '<article class="album-card">'+photo(a['cover'],a['title'])+'<div class="card-copy"><p class="eyebrow">'+a['date']+' · '+a['type']+'</p><h3>'+a['title']+'</h3><p>'+a['intro']+'</p>'+link('/bblo/community-impact/'+a['slug']+'/', 'Open album &amp; meet the organization →','text-link')+'</div></article>'
def partnercard(p):
 phone=re.sub(r'\D','',p['phone'])
 return '<article class="card partner-card"><p class="eyebrow">'+p['kind']+'</p><h3>'+esc(p['name'])+'</h3><p>'+esc(p['about'])+'</p><p><a href="tel:+1'+phone+'">'+p['phone']+'</a></p>'+('<p><a href="mailto:'+p['email']+'">'+p['email']+'</a></p>' if p['email'] else '')+('<p>'+esc(p['address'])+'</p>' if p['address'] else '')+'<div class="actions"><a class="button" href="'+p['website']+'" target="_blank" rel="noopener">Visit website ↗</a><a class="text-link" href="'+p['contact']+'" target="_blank" rel="noopener">Contact / get involved ↗</a></div><p class="note">Contact source: the organization’s official website · checked November 3, 2026.</p></article>'
for a in albums:
 gallery=''.join('<figure class="photo"><a href="'+BASE+'/assets/'+src+'" target="_blank" rel="noopener" aria-label="Open full photograph: '+esc(caption)+'"><img src="'+BASE+'/assets/'+src+'" alt="'+esc(caption)+'" loading="lazy" decoding="async"></a><figcaption>'+esc(caption)+'</figcaption></figure>' for src,caption in a['photos'])
 body=hero(a['type']+' · '+a['date'],a['title'],a['intro'])+section('<div class="split"><div><p class="eyebrow">What we were doing</p><h2>The activity behind the pictures.</h2><p>'+a['doing']+'</p></div><div class="editorial-note"><p>These albums connect BBLO’s local activities with the organizations and people doing the work in our community.</p></div></div><div class="gallery album-gallery">'+gallery+'</div>')
 if a['slug']=='community-nonprofit-spotlights':
  body+=section('<p class="eyebrow">From the meeting archive</p><h2>A moment from the conversation.</h2><p>An 11-second clip from the September 4 meeting archive. Play it when you’re ready.</p><video class="community-video" controls playsinline preload="none" poster="'+BASE+'/assets/bblo/community/nonprofit-group.webp"><source src="'+BASE+'/assets/bblo/community/nonprofit-spotlight-video.mp4" type="video/mp4">Your browser does not support this video.</video>','map-section')
 body+=section('<p class="eyebrow">Keep the connection going</p><h2>Meet the community partner'+('s' if len(a['partners'])>1 else '')+'.</h2><div class="grid">'+''.join(partnercard(partners[k]) for k in a['partners'])+'</div><div class="actions">'+link('/bblo/community-impact/','← All community albums','button secondary')+'</div>')
 page('/bblo/community-impact/'+a['slug']+'/',a['title'],a['intro'],body,a['cover'])
impact=hero('Our community impact','Business relationships.<br><em>Community connections.</em>','Explore BBLO activities, see the photographs, understand the context and connect directly with the organizations involved.')+section('<div class="grid album-grid">'+''.join(albumcard(a) for a in albums)+'</div>')+section('<h2>Have a community partnership in mind?</h2><p>Tell us about your organization, the need and how local businesses could participate.</p>'+link('/bblo/support/?interest=community','Start a community conversation'),'dark')
page('/bblo/community-impact/','Our Community Impact','BBLO activity albums, local nonprofit contacts and community partner websites.',impact)

hubhero=section('<div><p class="eyebrow">Bilingual Business Leaders of Ocala · A TLC program</p><h1>We build businesses.<br><em>Not just connections.</em></h1><p class="lead">Trusted relationships, business education, referrals and community participation for business owners in Ocala and Marion County.</p><p>You don’t have to speak Spanish to attend.</p><div class="actions">'+link('/bblo/join/','Come meet us')+link('/bblo/members/','Meet our members','button secondary')+'</div></div>'+photo('photos/bblo-october-group.webp','BBLO participants together at Media Minds.','BBLO / October 9, 2026.','bblo-hero-photo'),'hero bblo-hero')
hub=hubhero+section('<div class="split"><div><p class="eyebrow">About BBLO</p><h2>Get to know the business.<br>Build the relationship.</h2><p>BBLO helps local business owners build connections through member spotlights, practical learning, referrals and consistent participation.</p><p>Founded by Carmen Garcia Tirado, BBLO operates under The Liaison Companies LLC. Its bilingual, multicultural mission welcomes qualified business owners and professionals from different backgrounds.</p>'+link('/bblo/join/','See how to visit and join','text-link')+'</div>'+photo('photos/bblo-meeting-conversations.webp','Conversations around the BBLO meeting tables.','Real conversations / October 9, 2026.')+'</div>')
hub+=section('<p class="eyebrow">Explore BBLO</p><h2>Find your next connection.</h2><div class="grid three route-cards">'+''.join('<article class="card"><h3>'+label+'</h3><p>'+copy+'</p>'+link(path,'Explore →','text-link')+'</article>' for path,label,copy in [('/bblo/members/','Meet Our Members','Find a business, learn about its services and connect directly.'),('/bblo/board/','Meet Our Board','Meet the people helping guide BBLO.'),('/bblo/community-impact/','Our Community Impact','Open activity albums and connect with community partners.'),('/bblo/testimonials/','Member Stories','Read and share approved experiences from the people in BBLO.'),('/bblo/present/','Share Your Expertise','Propose a practical topic for our business community.'),('/bblo/support/','Support BBLO','Explore sponsorship, advertising and in-kind partnerships.')])+'</div>','map-section')
hub+=section('<p class="eyebrow">Beyond the meeting</p><h2>The people. The activity. The connection.</h2><div class="grid">'+albumcard(albums[0])+albumcard(albums[2])+'</div><div class="actions">'+link('/bblo/community-impact/','View all community albums','button secondary')+'</div>')
hub+=section('<div class="split"><div><p class="eyebrow">For members</p><h2>Check in.<br>Share what’s growing.</h2><p>Record a visit and add more than one win, with separate details for each introduction, collaboration or milestone.</p></div><div><div class="actions">'+link('/bblo/member-center/#member-check-in','Member check-in')+link('/bblo/member-center/#member-win','Report wins','button secondary')+'</div><p class="note">Form review only. Check-in, reporting and C-Suiteware notifications are not active.</p></div></div>','dark')
page('/bblo/','About BBLO','Bilingual business relationships, education, referrals and community participation in Ocala and Marion County.',hub)

join=hero('How to join','Start with a visit.<br><em>Build from there.</em>','Come meet local business owners, introduce your business and see how BBLO works.')+section('<div class="split"><div><h2>Your Friday connection.</h2><p>Regular meetings are <strong>Fridays, 8–10 AM at Media Minds in north Ocala.</strong> Field Trip Fridays may meet elsewhere. Confirm the upcoming meeting before traveling.</p><p>Your first two visits are free. Prepare a 30-second introduction: your name, your business, who you serve and the introduction you’re looking for.</p><p lang="es">No tienes que hablar español para unirte.</p><div class="actions">'+link('/inquire/?service=bblo-visit','Plan your visit')+'<a class="text-link" href="tel:3522079770">Confirm with Carmen · 352-207-9770</a></div></div>'+photo('photos/bblo-business-education.webp','A BBLO business education conversation.','Education and business conversation at Media Minds.')+'</div>')+section('<p class="eyebrow">From visitor to member</p><h2>Get to know us. Then apply.</h2><ol class="join-steps"><li><strong>Visit.</strong> Meet the group and introduce your business.</li><li><strong>Return and connect.</strong> Ask questions, learn about members and discuss the current membership process.</li><li><strong>Apply.</strong> Complete the current application and payment steps provided by BBLO.</li><li><strong>Review and onboarding.</strong> Membership is subject to committee review and final approval.</li></ol>'+link('/inquire/?service=bblo-membership','Ask about membership'))
investment_source=(ROOT/'bblo/join/index.html').read_text() if (ROOT/'bblo/join/index.html').exists() else template
investment=re.search(r'<section class=""><div class="wrap"><p class="eyebrow">Membership investment.*?</section>',investment_source,re.S).group()
join+=investment
page('/bblo/join/','How to Join','Visit a BBLO meeting, learn about membership and review the current fee options.',join)
board=hero('Meet our board','The people behind<br><em>the community.</em>','Leadership profiles are published with confirmed names, roles, photographs and biographies.')+section('<div class="split"><div><p class="eyebrow">Founder &amp; President</p><h2>Carmen Garcia Tirado</h2><p>Founder and owner of The Liaison Companies LLC. Carmen leads BBLO’s work connecting local business owners through relationships, education and community involvement.</p>'+link('/bblo/members/tlc/','Meet Carmen &amp; connect','button')+'</div>'+photo('photos/carmen-portrait.jpg','Carmen Garcia Tirado.','Carmen Garcia Tirado / BBLO Founder &amp; President.','member-profile-photo')+'</div><p class="review-note">Board review: additional names, titles, photos and biographies are awaiting confirmation.</p>')
page('/bblo/board/','Meet Our Board','Meet BBLO’s confirmed leadership.',board,'photos/carmen-portrait.jpg')

def field(label,name,kind='text',required=True,options=None):
 req=' required' if required else '';id='f-'+name
 if options:control=f'<select id="{id}" name="{name}"{req}><option value="">Choose…</option>'+''.join('<option>'+esc(x)+'</option>' for x in options)+'</select>'
 elif kind=='textarea':control=f'<textarea id="{id}" name="{name}"{req}></textarea>'
 else:control=f'<input id="{id}" name="{name}" type="{kind}"{req}>'
 return '<div class="form-field"><label for="'+id+'">'+label+(' *' if required else ' (optional)')+'</label>'+control+'</div>'
def identity(prefix):return field('Your name',prefix+'name')+field('Business name',prefix+'business')+field('Email',prefix+'email','email')
def form(title,id,content,permission='I agree that Carmen may contact me about this request.'):
 return '<article class="inquiry-form" id="'+id+'"><h2>'+title+'</h2><form class="bblo-review-form" onsubmit="return false"><div class="form-grid">'+content+'</div><label class="form-consent"><input type="checkbox" data-consent required>'+permission+'</label><button type="submit" class="button">Review my answers</button><p class="form-status">Review only — nothing is sent or saved.</p><div class="form-summary" tabindex="-1" role="status" hidden></div></form></article>'
def form_notice():return '<div class="review-note"><strong>Form preview.</strong> These forms do not send, save or publish information. Use sample details while reviewing.</div>'
win_types=['Introduction / referral','Business received','Collaboration','One-to-one','Community contribution','Milestone']
def winlist(id,optional=False):
 toggle='<label class="form-consent"><input type="checkbox" data-win-toggle data-ui>Add wins to this check-in</label>' if optional else ''
 checks=''.join('<label class="checkbox-option"><input type="checkbox" name="wins[__INDEX__][types]" value="'+esc(t)+'" data-win-type> '+t+'</label>' for t in win_types)
 item='<fieldset data-win-entry><legend>Win <span data-win-number>1</span></legend><p class="note">Choose every type that applies to this win. Add a separate entry for a different win.</p><div class="checkbox-grid">'+checks+'</div><div class="form-grid">'+field('Date of win',id+'-__INDEX__-date','date')+field('People or businesses involved',id+'-__INDEX__-people',required=False)+field('What happened?',id+'-__INDEX__-description','textarea')+field('Value in USD',id+'-__INDEX__-value','number',False)+field('Supporting link',id+'-__INDEX__-link','url',False)+field('Sharing preference',id+'-__INDEX__-sharing',options=['Private tracking only','Contact me to approve a public story'])+'</div><button type="button" class="text-button" data-remove-win>Remove this win</button></fieldset>'
 return '<div class="win-builder" data-win-builder>'+toggle+'<div data-win-area'+(' hidden' if optional else '')+'><div data-win-list></div><button type="button" class="button secondary" data-add-win>Add another win</button><p class="note" data-win-count aria-live="polite"></p></div><template data-win-template>'+item+'</template></div>'
visitor=form('Visitor check-in','visitor-check-in',identity('visitor-')+field('Phone','visitor-phone','tel',False)+field('Meeting date','visitor-date','date')+field('Business category','visitor-category')+field('Visit','visitor-type',options=['First visit','Returning visitor'])+field('Who invited you?','visitor-referral',required=False)+field('Preferred language','visitor-language',required=False,options=['English','Español','Either']))
member=form('Member check-in','member-check-in',identity('member-')+field('Meeting date','member-date','date')+'</div>'+winlist('attendance',True)+'<div>','I confirm this check-in is for me. Attendance and any wins are for review; membership status must be verified before they are recorded.')
win=form('Report one or more wins','member-win',identity('report-')+'</div>'+winlist('report')+'<div>','I confirm these reports are accurate. Public stories require a separate review and approval.')
center=hero('Member check-in & wins','Every visit.<br><em>Every win has a story.</em>','Check in and add multiple wins, with separate details for each. You can also report wins between meetings.','<div class="actions">'+link('/bblo/member-center/#member-check-in','Member check-in')+link('/bblo/member-center/#member-win','Report wins','button secondary')+link('/bblo/member-center/#visitor-check-in','Visitor check-in','button secondary')+'</div>')+section(form_notice()+'<p class="note">This review page is not an authenticated member portal. C-Suiteware capture, attendance records and notifications remain unconnected.</p><div class="bblo-form-stack">'+member+win+visitor+'</div>')
page('/bblo/member-center/','Member Check-in & Multiple Wins','Preview member and visitor check-in and report multiple BBLO wins.',center)

storyfields=identity('story-')+field('Your BBLO experience, in your own words','story-quote','textarea')+field('One specific example, introduction, referral, lesson or opportunity','story-example','textarea')+field('How long have you participated?','story-time',required=False)+field('Photo or video link','story-media','url',False)+field('Photo/video credit','story-credit',required=False)+field('May BBLO publish your quote, name and company?','story-quote-permission',options=['Contact me before publishing','Yes, after BBLO reviews it'])+field('May BBLO use the linked photo/video?','story-media-permission',required=False,options=['No media supplied','Contact me before using it','Yes, I have permission for BBLO to use it'])
profilefields=identity('profile-')+field('Business phone','profile-phone','tel',False)+field('Public business email','profile-public-email','email',False)+field('Website','profile-website','url',False)+field('Facebook profile/page URL','profile-facebook','url',False)+field('Instagram URL','profile-instagram','url',False)+field('Photo link','profile-photo','url',False)+field('Original logo link','profile-logo','url',False)+field('Photo/logo credit and permission','profile-permission','textarea')+field('What should your profile say?','profile-description','textarea')
approved_stories=''.join('<article class="card"><blockquote class="member-quote"><p>'+esc(m['quote'])+'</p><cite>'+esc(m['name'])+' · '+esc(m['company'])+'</cite></blockquote></article>' for m in members if m.get('quote') and m.get('quote_approved'))
testimonials=hero('Testimonials & member stories','What has BBLO<br><em>made possible for you?</em>','Real experiences from real members. Quotes, photos and videos are reviewed and shared with permission.')+(section('<div class="grid">'+approved_stories+'</div>') if approved_stories else '')+section('<div class="split"><div><p class="eyebrow">A question worth answering</p><h2>Tell us one specific story.</h2><p>What has changed for your business because of BBLO? Share an introduction, referral, lesson, collaboration or opportunity, and why it mattered.</p><p>Keep it in your own words. A short quote or video is welcome.</p></div><div class="editorial-note"><p class="lead">Your words. Your experience.</p><p>Tell us what happened, who made the connection and why it mattered to your business.</p></div></div>'+form_notice()+'<div class="bblo-form-stack">'+form('Share your BBLO story','share-story',storyfields)+form('Update your member profile','profile-update',profilefields)+'</div>')
page('/bblo/testimonials/','Testimonials & Member Stories','Share a real BBLO experience, member quote, photograph or video for review.',testimonials)
present=hero('Interested in presenting?','Teach something<br><em>our businesses can use.</em>','Bring practical knowledge, a useful takeaway and a topic relevant to business owners in Marion County.')+section('<div class="grid three"><article class="card"><h3>Be useful.</h3><p>Tell us what members will learn and how they can apply it.</p></article><article class="card"><h3>Know the audience.</h3><p>Shape the topic for local business owners and professionals.</p></article><article class="card"><h3>Start a conversation.</h3><p>Share your proposed format and leave space for relevant questions.</p></article></div>'+form_notice()+form('Propose a presentation','presenter-request',identity('presenter-')+field('Phone','presenter-phone','tel',False)+field('Proposed topic','presenter-topic')+field('What will attendees learn?','presenter-takeaway','textarea')+field('Relevant experience','presenter-experience','textarea')+field('Preferred format','presenter-format',options=['Presentation and Q&A','Interactive workshop','Panel conversation','Other format to discuss'])+field('Requested time / length','presenter-duration',required=False)+field('Available dates','presenter-dates',required=False)+field('Website or sample presentation','presenter-link','url',False)))
page('/bblo/present/','Interested in Presenting?','Propose a practical business education topic for BBLO.',present)
choices=''.join('<label class="checkbox-option"><input type="checkbox" name="support-types" value="'+t+'"> '+t+'</label>' for t in ['Sponsor business education','Advertise my business','Provide in-kind support','Discuss a community partnership'])
support=hero('Support BBLO','Help our business<br><em>community keep growing.</em>','Explore ways to support business education, member visibility and community connections in Marion County.')+section('<div class="grid three"><article class="card"><h3>Sponsor.</h3><p>Discuss supporting a business education activity or approved BBLO initiative.</p></article><article class="card"><h3>Advertise.</h3><p>Ask about business visibility opportunities. Any paid placement will be clearly identified.</p></article><article class="card"><h3>Contribute.</h3><p>Explore in-kind resources or a community partnership with a clear local purpose.</p></article></div><p>Availability, fit, deliverables and any pricing are discussed before an arrangement is confirmed.</p>'+form_notice()+form('Start a support conversation','support-request',identity('support-')+field('Phone','support-phone','tel',False)+'<div class="form-field full"><p class="directory-label">What would you like to discuss? Choose all that apply.</p><div class="checkbox-grid">'+choices+'</div></div>'+field('What would you like to support or promote?','support-details','textarea')+field('Timing','support-timing',required=False)+field('Budget or in-kind resource','support-budget',required=False)+field('Website','support-website','url',False)))
page('/bblo/support/','Support BBLO','Discuss BBLO sponsorship, advertising, in-kind support and community partnerships.',support)

# Shared navigation is the same from every TLC review page.
for file in ROOT.rglob('index.html'):
 if file==ROOT/'index.html':continue
 s=file.read_text()
 s=s.replace(f'<a href="{BASE}/bblo/">BBLO</a>',dropdown)
 s=re.sub(r'(/assets/(?:design\.css|site\.js))(?:\?v=[^"\s]+)?',r'\1?v='+VERSION,s)
 file.write_text(s)

# Legacy hash bookmarks now route to native pages rather than downloading every page.
routes=['/'+str(p.parent.relative_to(ROOT)).strip('/')+'/' for p in ROOT.rglob('index.html') if p!=ROOT/'index.html']
bridge='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>TLC Website Review</title></head><body><p><a href="/website-preview/home/">Open the TLC website review</a></p><p><a href="/website-preview/bblo/">Open BBLO</a></p><script>const routes=ROUTES;let requested=location.hash.startsWith('#/')?location.hash.slice(1):'/home/';const path=requested.split(/[?#]/)[0];if(!routes.includes(path))requested='/home/';location.replace('/website-preview'+requested);</script></body></html>'''.replace('ROUTES',json.dumps(routes))
(ROOT/'index.html').write_text(bridge)
print('Built BBLO sections, 17 member profiles, 3 activity albums and native-page navigation.')
